            result["content"] = self._process_content(content, config)
            result["metadata"] = {
                "number_of_paragraphs": len(doc.paragraphs),
                "number_of_tables": len(tables),
                "number_of_headings": len(headings)
            }

        # 返回解析结果
        return {
            "output1": result
        }

    def _process_content(self, content, config):
        """处理内容并根据配置提取片段"""
